-bold"><?= (int)$item['id'] ?></td><td><form class="d-flex gap-2" method="post" action="?c=Academic&a=update"><input type="hidden" name="section" value="<?= htmlspecialchars($section) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input class="form-control form-control-sm" name="name" value="<?= htmlspecialchars($item['nombre'],ENT_QUOTES,'UTF-8') ?>" required><button class="btn btn-sm btn-outline-warning" title="Guardar edición"><i class="bi bi-pencil"></i></button></form></td><td class="text-end pe-4"><span class="text-muted small">Activo</span></td></tr><?php endforeach;?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
